+	const literals: string[] = [];
+	let protectedPattern = '';
+	let index = 0;
+
+	const addLiteral = (literal: string): void => {
+		protectedPattern += `${BRACE_EXPANSION_LITERAL_PREFIX}${literals.length}\0`;
